#include <iostream>
using namespace std;

class FishBag {
    int count;
public:
    FishBag(int c) : count(c) {}
    friend ostream& operator<<(ostream& os, const FishBag& bag);
};

ostream& operator<<(ostream& os, const FishBag& bag) {
    os << bag.count;
    return os;
}

int main() {
    FishBag a({n});
    cout << a << endl;
    return 0;
